        "code": "\"use client\"\n\nimport { createColumnHelper } from \"@tanstack/react-table\"\nimport {\n  EllipsisIcon,\n  KeyRoundIcon,\n  PencilIcon,\n  ShieldIcon,\n} from \"lucide-react\"\n\nimport { Button } from \"@/components/ui/button\"\nimport {\n  DropdownMenu,\n  DropdownMenuContent,\n  DropdownMenuItem,\n  DropdownMenuTrigger,\n} from \"@/components/ui/dropdown-menu\"\nimport {\n  DataTableColumnHeader,\n  type DataTableFeatures,\n} from \"@/components/blocks/openlmis/data-table/data-table\"\nimport type { ResponsiveColumn } from \"@/components/blocks/openlmis/data-table/responsive-columns\"\nimport { StatusBadge } from \"@/components/openlmis/status-badge\"\n\nimport type { User } from \"@/components/openlmis/list-page/mock-users\"\n\n/** The columns the View menu lists, in order; `hideBelow` drops them while the table is narrow. */\nexport const HIDEABLE_COLUMNS: (ResponsiveColumn & { label: string })[] = [\n  { id: \"lastName\", label: \"Name\", hideBelow: \"xl\" },\n  { id: \"email\", label: \"Email\", hideBelow: \"4xl\" },\n  { id: \"active\", label: \"Status\" },\n]\n\nconst columnHelper = createColumnHelper<DataTableFeatures, User>()\n\nexport const userColumns = columnHelper.columns([\n  // Shows the full name but sorts by last name, the usual order for a list of people.\n  columnHelper.accessor(\"lastName\", {\n    header: ({ column }) => (\n      <DataTableColumnHeader column={column} title=\"Name\" />\n    ),\n    cell: ({ row }) => `${row.original.firstName} ${row.original.lastName}`,\n    meta: { className: \"@xl/table:w-2/5 @4xl/table:w-1/5\" },\n  }),\n  columnHelper.accessor(\"username\", {\n    header: ({ column }) => (\n      <DataTableColumnHeader column={column} title=\"Username\" />\n    ),\n    cell: ({ getValue }) => <span className=\"font-medium\">{getValue()}</span>,\n    // No width below 4xl, so the username takes the room the hidden columns leave.\n    meta: { className: \"@4xl/table:w-1/6\" },\n  }),\n  columnHelper.accessor(\"email\", {\n    header: ({ column }) => (\n      <DataTableColumnHeader column={column} title=\"Email\" />\n    ),\n    cell: ({ getValue }) =>\n      getValue() ?? <span className=\"text-muted-foreground\">-</span>,\n    enableSorting: false,\n  }),\n  columnHelper.accessor(\"active\", {\n    header: ({ column }) => (\n      <DataTableColumnHeader column={column} title=\"Status\" />\n    ),\n    cell: ({ getValue }) =>\n      getValue() ? (\n        <StatusBadge tone=\"success\">Active</StatusBadge>\n      ) : (\n        <StatusBadge tone=\"destructive\">Inactive</StatusBadge>\n      ),\n    meta: { className: \"w-32\" },\n  }),\n  columnHelper.display({\n    id: \"actions\",\n    header: () => <span className=\"sr-only\">Actions</span>,\n    cell: ({ row }) => <UserActions username={row.original.username} />,\n    meta: { className: \"w-16\" },\n  }),\n])\n\n// Wire these to real screens; they do nothing in the template.\nfunction UserActions({ username }: { username: string }) {\n  return (\n    <div className=\"flex justify-end\">\n      <DropdownMenu>\n        <DropdownMenuTrigger\n          render={\n            <Button\n              aria-label={`Actions for ${username}`}\n              size=\"icon-sm\"\n              variant=\"ghost\"\n            />\n          }\n        >\n          <EllipsisIcon />\n        </DropdownMenuTrigger>\n        <DropdownMenuContent align=\"end\" className=\"w-auto\">\n          <DropdownMenuItem>\n            <PencilIcon />\n            Edit\n          </DropdownMenuItem>\n          <DropdownMenuItem>\n            <ShieldIcon />\n            Roles\n          </DropdownMenuItem>\n          <DropdownMenuItem variant=\"destructive\">\n            <KeyRoundIcon />\n            Reset Password\n          </DropdownMenuItem>\n        </DropdownMenuContent>\n      </DropdownMenu>\n    </div>\n  )\n}",
